public static function sendCustomCommand(data:Dynamic) {
		#if DISCORD_RPC
		if(data == null) return;
		if(data.nonce == null) data.nonce = getUUID();
		var json = Json.stringify(data);
		Discord.SendCustomCommand(json);
		#end
	}

